import{_ as t,c as a,o,ao as s}from"./chunks/framework.C3XuLvUm.js";const m=JSON.parse('{"title":"组件编组","description":"","frontmatter":{},"headers":[],"relativePath":"docs/pogget/group.md","filePath":"docs/pogget/group.md"}'),r={name:"docs/pogget/group.md"};function c(p,e,d,_,n,i){return o(),a("div",null,e[0]||(e[0]=[s('<h1 id="组件编组" tabindex="-1">组件编组 <a class="header-anchor" href="#组件编组" aria-label="Permalink to &quot;组件编组&quot;">​</a></h1><p>###设置颜色 相同颜色的标签的组件可以进行编组。在编组后，相同颜色且临近的组件将被磁力吸附。窗口位置、窗口大小等的调整都会影响附近的相同编组窗口。通过编组窗口，您可以轻松实现灵活的窗口布局。</p><blockquote><p>若将颜色设置为白色，则其将被视为未编组。 <img src="https://github.com/user-attachments/assets/64c007e1-8320-4fc5-ba8d-219abedb0f88" alt="explorer_JY4FZ6BQxd"></p></blockquote><p>###合并和群组 组件在编组后，可以将相同标签的组件合并为一个大组件。合并后的位置与先前的位置是相互独立的。 <img src="https://github.com/user-attachments/assets/586e467b-f043-42e5-8ea8-cfdd093783ae" alt="explorer_6aIq51AM68"></p><p>###临时解除编组 若在编组后需要调整组件位置、大小，可以按住 CTRL 键再进行调整。 <img src="https://github.com/user-attachments/assets/a6e972e4-3c35-4562-a5fb-aba19e418dee" alt="explorer_O4kWdzB9cx"></p>',5)]))}const u=t(r,[["render",c]]);export{m as __pageData,u as default};
